SELECT *
FROM
`inspection`.`inspection_working_paper` a
WHERE 1=1

    AND a.`TASK_ID` = #{params.TASK_ID}


    AND a.`ADD_USERID` = #{params.ADD_USERID}

mapper.update:
UPDATE `inspection`.`inspection_working_paper` a
SET
    a.CHECK_ITEMS_CONTENT = #{params.CHECK_ITEMS_CONTENT},
    a.MODIFY_DATE         = #{params.MODIFY_DATE}
WHERE
    ((a.`PAPER_ID` = #{params.PAPER_ID})
     OR
     (
         a.`TASK_ID` = #{params.TASK_ID}
         AND a.`ADD_USERID` = #{params.ADD_USERID}
     ))

